// gh2gfx/d3d_probe.h - discovery probe for the D3D library that is linked into the game (0x823B0000-0x823E0000, 909 functions).
//
// The library has no symbols, so the roles of its functions are found by watching them: with GH2_D3D_PROBE=<prefix> every function of the
// block (hooks generated by native/tools/gen_d3d_probes.py) records, for its first calls, the six argument registers, the return value and
// the first word of memory each argument points to (before and after the call), into <prefix>.events; <prefix>.functions lists the
// function table. native/tools/d3d_probe_report.py reads the two. Off by default: a hooked function then only calls the original.
//
// Besides the capped first calls of every function there is a WINDOW mode (GH2_D3D_PROBE_WINDOW=<first frame>:<frames>, frames counted by the VdSwap hook):
// inside it every call of every function is recorded, together with 64 bytes of memory behind each pointer argument (<prefix>.dumps) and the PM4 words the
// call appended to the command buffer (<prefix>.pm4), which ties a function to the GPU registers it writes. <prefix>.counts has the exact number of calls.
//
// Guest side only (shim headers); no SDK header, no `rex::` (native/tools/check_isolation.sh).
#pragma once

#include <cstdint>

namespace gh2gfx::d3d {

namespace detail {
extern bool g_probe_on;  // set once, before main(), from the environment
}
inline bool ProbeEnabled() { return detail::g_probe_on; }

// `index` is the position of the function in the generated table (kProbeFunctions); `args` are r3..r8; `base` translates guest addresses.
void ProbeEnter(uint32_t index, const uint32_t (&args)[6], const uint8_t* base);
void ProbeLeave(uint32_t index, uint32_t ret, const uint32_t (&args)[6], const uint8_t* base);

// Called by the VdSwap hook with the import's r3..r8: counts frames (the window mode's clock) and records a frame mark (function 0xFFFF, phase 2).
void ProbeFrameMark(const uint32_t (&args)[6], const uint8_t* base);
// Called by the draw-state commit hook: the device whose command pointer (+48) the window mode reads around every call.
void ProbeSetDevice(uint32_t device);

// The generated table of probed functions: guest addresses in ascending order. It also lists the functions that have a hand-written hook (d3d_hooks.cpp):
// those record themselves through ProbeScope.
extern const uint32_t kProbeFunctions[];
extern const uint32_t kProbeFunctionCount;
// Position of `address` in kProbeFunctions (the index ProbeEnter wants), or 0xFFFFFFFF when it is not probed.
uint32_t ProbeIndexOf(uint32_t address);

// On-disk record of <prefix>.events (little endian, 64 bytes).
struct ProbeEvent {
  uint32_t seq;        // global order
  uint16_t function;   // index into kProbeFunctions
  uint8_t phase;       // 0 = entry, 1 = exit
  uint8_t thread;      // small host-thread number
  uint32_t args[6];    // r3..r8 at entry
  uint32_t ret;        // r3 at exit (0 at entry)
  uint32_t deref[6];   // big-endian first word at each argument that looks like a guest pointer, host order here; 0xFFFFFFFF = not a pointer
  uint32_t reserved;
};
static_assert(sizeof(ProbeEvent) == 64, "ProbeEvent is 64 bytes");

// <prefix>.dumps (window mode): the 64 bytes behind one pointer argument, as they were at entry (phase 0) or exit (phase 1) of the call with this seq.
struct ProbeDump {
  uint32_t seq;
  uint8_t phase;
  uint8_t arg;       // 0..5 = r3..r8
  uint16_t reserved;
  uint8_t bytes[64];  // guest memory as is (big endian)
};
static_assert(sizeof(ProbeDump) == 72, "ProbeDump is 72 bytes");
// <prefix>.pm4 (window mode): per call that moved the command pointer: ProbePm4Header followed by `words` big-endian dwords (the packets it wrote).
struct ProbePm4Header {
  uint32_t seq;      // of the exit event
  uint32_t first;    // guest address of the first dword written
  uint32_t words;
};

}  // namespace gh2gfx::d3d
